/**
 * @brief Check if address is in read-only section.
 *
 * @param addr Address.
 *
 * @return True if address identified within read-only section, false
 * otherwise.
 */
static inline bool ptr_in_rodata(const char *addr)
{
#if defined(CBPRINTF_VIA_UNIT_TEST)
	/* Unit test is Mapping RODATA only for some platforms. */
	return false;
#else
	return linker_is_in_rodata(addr);
#endif
}

/*
 * va_list creation
 */

#if defined(__aarch64__)
/*
 * Reference:
 *
 * Procedure Call Standard for the ARM 64-bit Architecture
 */
struct __va_list {
	void	*__stack;
	void	*__gr_top;
	void	*__vr_top;
	int	__gr_offs;
	int	__vr_offs;
};

BUILD_ASSERT(sizeof(va_list) == sizeof(struct __va_list),
	     "architecture specific support is wrong");

static int cbprintf_via_va_list(cbprintf_cb out,
				cbvprintf_external_formatter_func formatter,
				void *ctx,
				const char *fmt, void *buf)
{
	union {
		va_list ap;
		struct __va_list __ap;
	} u;

	/* create a valid va_list with our buffer */
	u.__ap.__stack = buf;
	u.__ap.__gr_top = NULL;
	u.__ap.__vr_top = NULL;
	u.__ap.__gr_offs = 0;
	u.__ap.__vr_offs = 0;

	return formatter(out, ctx, fmt, u.ap);
}

#elif defined(__x86_64__)
/*
 * Reference:
 *
 * System V Application Binary Interface
 * AMD64 Architecture Processor Supplement
 */
struct __va_list {
	unsigned int gp_offset;
	unsigned int fp_offset;
	void *overflow_arg_area;
	void *reg_save_area;
};

BUILD_ASSERT(sizeof(va_list) == sizeof(struct __va_list),
	     "architecture specific support is wrong");

static int cbprintf_via_va_list(cbprintf_cb out,
				cbvprintf_external_formatter_func formatter,
				void *ctx,
				const char *fmt, void *buf)
{
	union {
		va_list ap;
		struct __va_list __ap;
	} u;

	/* create a valid va_list with our buffer */
	u.__ap.overflow_arg_area = buf;
	u.__ap.reg_save_area = NULL;
	u.__ap.gp_offset = (6 * 8);
	u.__ap.fp_offset = (6 * 8 + 16 * 8);

	return formatter(out, ctx, fmt, u.ap);
}

#elif defined(__xtensa__)
/*
 * Reference:
 *
 * gcc/config/xtensa/xtensa.c
 *
 * Look for xtensa_build_builtin_va_list(), xtensa_va_start() and
 * xtensa_gimplify_va_arg_expr(). Args are passed in registers first:
 * AR[2] to AR[7]. Simply setting __va_ndx to the overflow threshold
 * value of (6 * 4) makes things fetched from the stack area which we
 * hijack with our buffer.
 */
struct __va_list {
	void *__va_stk;
	void *__va_reg;
	int __va_ndx;
};

BUILD_ASSERT(sizeof(va_list) == sizeof(struct __va_list),
	     "architecture specific support is wrong");

static int cbprintf_via_va_list(cbprintf_cb out,
				cbvprintf_external_formatter_func formatter,
				void *ctx,
				const char *fmt, void *buf)
{
	union {
		va_list ap;
		struct __va_list __ap;
	} u;

	/* create a valid va_list with our buffer */
	u.__ap.__va_stk = (char *)buf - 32;
	u.__ap.__va_reg = NULL;
	u.__ap.__va_ndx = 6 * 4;

	return formatter(out, ctx, fmt, u.ap);
}

#elif defined(__sh__)
/*
 * Reference:
 *
 * gcc/config/sh/sh.cc
 *
 * Look for sh_build_builtin_va_list(), sh_va_start() and
 * sh_gimplify_va_arg_expr().
 * When -m4-nofpu is passed, va_list is a simple pointer.
 */
#if defined(__SH4_NOFPU__)
static int cbprintf_via_va_list(cbprintf_cb out,
				cbvprintf_external_formatter_func formatter,
				void *ctx,
				const char *fmt, void *buf)
{
	union {
		va_list ap;
		void *ptr;
	} u;

	u.ptr = buf;

	return formatter(out, ctx, fmt, u.ap);
}
#else
struct __va_list {
	void *__va_next_o;
	void *__va_next_o_limit;
	void *__va_next_fp;
	void *__va_next_fp_limit;
	void *__va_next_stack;
};

BUILD_ASSERT(sizeof(va_list) == sizeof(struct __va_list),
	     "architecture specific support is wrong");

static int cbprintf_via_va_list(cbprintf_cb out,
				cbvprintf_external_formatter_func formatter,
				void *ctx,
				const char *fmt, void *buf)
{
	union {
		va_list ap;
		struct __va_list __ap;
	} u;

	/* create a valid va_list with our buffer */
	u.__ap.__va_next_o = buf;
	u.__ap.__va_next_o_limit = buf;
	u.__ap.__va_next_fp = buf;
	u.__ap.__va_next_fp_limit = buf;
	u.__ap.__va_next_stack = buf;

	return formatter(out, ctx, fmt, u.ap);
}
#endif /* __SH4_NOFPU__ */
#else
/*
 * Default implementation shared by many architectures like
 * 32-bit ARM and Intel, 32/64-bit RISC-V, etc.
 *
 * Here va_list is simply a pointer to the argument storage area.
 */
BUILD_ASSERT(sizeof(va_list) == sizeof(void *),
	     "architecture specific support is needed");

static int cbprintf_via_va_list(cbprintf_cb out,
				cbvprintf_external_formatter_func formatter,
				void *ctx,
				const char *fmt, void *buf)
{
	union {
		va_list ap;
		void *ptr;
	} u;

	u.ptr = buf;

	return formatter(out, ctx, fmt, u.ap);
}

#endif

static size_t get_package_len(void *packaged)
{
	__ASSERT_NO_MSG(packaged != NULL);

	uint8_t *buf0 = packaged;
	unsigned int *buf = packaged;

	uint8_t len = buf[0] & 0xff;
	uint8_t str_cnt = (buf[0] >> 8) & 0xff;
	uint8_t ro_str_cnt = (buf[0] >> 16) & 0xff;

	/* Skip past header and argument list. */
	buf0 += len * sizeof(int);

	/* Skip past appended read-only string indexes. */
	buf0 += ro_str_cnt;

	/* Skip past appended strings. */
	for (uint8_t i = 0; i < str_cnt; i++) {
		/* Skip past string Position index. */
		buf0++;
		/* Skip past null-terminated string. */
		buf0 += strlen((const char *)buf0) + 1;
	}

	return (size_t)(uintptr_t)(buf0 - (uint8_t *)packaged);
}

int z_cbvprintf_packaged(void *packaged, size_t len, uint32_t flags,
			 const char *fmt, va_list ap)
{
	uint8_t *buf0 = packaged;
	uint8_t *buf = buf0;
	unsigned int size;
	unsigned int align;
	uint8_t str_ptr_arg_pos = 0;
	/* Callback pointer table with index of the argument and pointer to a
	 * string.
	 */
	struct {
		uint8_t arg_idx;
		const char *ptr;
	} str_ptrs[16];
	/* Table with byte indices of read-only strings. */
	uint8_t ro_str_pos[16];
	uint8_t s_idx = 0;
	uint8_t ros_idx = 0;
	size_t pkg_offset = (flags & CBPRINTF_PACKAGE_FIRST_RO_STR_BITS_MASK);
	bool fsc = ((flags & CBPRINTF_PACKAGE_ADD_STRING_IDXS) != 0) &&
		   ((flags & CBPRINTF_PACKAGE_ADD_RW_STR_POS) != 0);
	/* Retrieve boolean flags from flags field. */
	bool parse_ro_str = fsc || (pkg_offset > 0) ||
			    (flags & CBPRINTF_PACKAGE_ADD_RO_STR_POS);
	bool store_ro_str_idx = (flags & CBPRINTF_PACKAGE_ADD_RO_STR_POS);

	/* Buffer must be aligned at least to size of a pointer. */
	if ((uintptr_t)packaged % sizeof(void *)) {
		return -EFAULT;
	}

#if defined(__xtensa__)
	/* Xtensa requires package to be 16 bytes aligned. */
	if ((uintptr_t)packaged % CBPRINTF_PACKAGE_ALIGNMENT) {
		return -EFAULT;
	}
#endif

	/*
	 * Leave room to store the arg list size and the format
	 * string pointer. Both are stored as 'unsigned int' (at least
	 * 1-int for header + 1 or 2 ints for format string pointer).
	 */
	buf += sizeof(int) + sizeof(fmt);

	/*
	 * If the current position is not aligned to the natural alignment
	 * of pointer, pad it.
	 */
	align = VA_STACK_ALIGN(char *);
	if (sizeof(void *) > sizeof(int)) {
		buf = (void *)ROUND_UP(buf, align);
	}

	/*
	 * Parse the format string to retrieve arguments.
	 * Track argument index as integers (sizeof(int)) in the buffer.
	 */
	if (fmt == NULL) {
		return -EINVAL;
	}

	while (pkg_offset > 0) {
		ro_str_pos[ros_idx++] = 1;
		pkg_offset--;
	}

	/* Formatting string is the first string, at index 1. */
	str_ptr_arg_pos = 1;

	for (unsigned int i = 0; fmt[i] != '\0'; i++) {
		if (fmt[i] != '%') {
			continue;
		}
		if (fmt[i + 1] == '%') {
			i++;
			continue;
		}

		/*
		 * We have a format specifier. Determine the size and
		 * alignment of the corresponding argument.
		 * Default is an 'int'.
		 */
		size = sizeof(int);
		align = VA_STACK_ALIGN(int);
		bool is_str = false;

		do {
			i++;
			switch (fmt[i]) {
			case '\0':
				/* End of string within format specifier - ignore */
				break;
			case '*':
				/*
				 * Dynamic field width or precision:
				 * there is an 'int' argument before
				 * the actual argument to format.
				 */
				buf = (void *)ROUND_UP(buf, VA_STACK_ALIGN(int));
				buf += sizeof(int);
				if (buf0 != NULL) {
					if ((size_t)(buf - buf0) > len) {
						return -ENOSPC;
					}
					*(int *)(buf - sizeof(int)) =
						va_arg(ap, int);
				}
				continue;
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
			case '.':
			case '+':
			case '-':
			case ' ':
			case '#':
			case '\'':
			case 'I':
			case 'h':
				/*
				 * Flags, width, precision, and 'short'
				 * modifiers don't change the type on
				 * the stack (promoted to 'int').
				 */
				continue;
			case 'l':
				if (fmt[i + 1] == 'l') {
					i++;
					size = sizeof(long long);
					align = VA_STACK_ALIGN(long long);
				} else {
					size = sizeof(long);
					align = VA_STACK_ALIGN(long);
				}
				continue;
			case 'j':
				size = sizeof(intmax_t);
				align = VA_STACK_ALIGN(intmax_t);
				continue;
			case 'z':
				size = sizeof(size_t);
				align = VA_STACK_ALIGN(size_t);
				continue;
			case 't':
				size = sizeof(ptrdiff_t);
				align = VA_STACK_ALIGN(ptrdiff_t);
				continue;
			case 'L':
				size = sizeof(long double);
				align = VA_STACK_ALIGN(long double);
				continue;
			case 'c':
			case 'd':
			case 'i':
			case 'o':
			case 'u':
			case 'x':
			case 'X':
				break;
			case 's':
				is_str = true;
				__fallthrough;
			case 'p':
			case 'n':
				size = sizeof(void *);
				align = VA_STACK_ALIGN(void *);
				break;
			case 'a':
			case 'A':
			case 'e':
			case 'E':
			case 'f':
			case 'F':
			case 'g':
			case 'G':
				if (size != sizeof(long double)) {
					size = sizeof(double);
					align = VA_STACK_ALIGN(double);
				}
				break;
			default:
				return -EINVAL;
			}

			break;
		} while (true);

		if (fmt[i] == '\0') {
			break;
		}

		/* Align the buffer pointer for the current argument. */
		buf = (void *)ROUND_UP(buf, align);
		str_ptr_arg_pos = (buf - buf0) / sizeof(int);

		/* Copy the argument data from va_list to the buffer. */
		if (buf0 != NULL) {
			if ((size_t)(buf - buf0 + size) > len) {
				return -ENOSPC;
			}

			if (is_str) {
				const char *s = va_arg(ap, const char *);

				*(const char **)buf = s;
				if (fsc) {
					/* In case of FSC package all strings
					 * must be appended.
					 */
					if (s_idx >= ARRAY_SIZE(str_ptrs)) {
						return -EINVAL;
					}

					str_ptrs[s_idx].ptr = s;
					str_ptrs[s_idx].arg_idx = str_ptr_arg_pos;
					s_idx++;
				} else if (parse_ro_str) {
					if (ptr_in_rodata(s)) {
						if (store_ro_str_idx) {
							if (ros_idx >= ARRAY_SIZE(ro_str_pos)) {
								return -EINVAL;
							}

							ro_str_pos[ros_idx++] = str_ptr_arg_pos;
						}
					} else {
						if (s_idx >= ARRAY_SIZE(str_ptrs)) {
							return -EINVAL;
						}

						str_ptrs[s_idx].ptr = s;
						str_ptrs[s_idx].arg_idx = str_ptr_arg_pos;
						s_idx++;
					}
				}
			} else if (size == sizeof(int)) {
				*(int *)buf = va_arg(ap, int);
			} else if (size == sizeof(long)) {
				*(long *)buf = va_arg(ap, long);
			} else if (size == sizeof(long long)) {
				*(long long *)buf = va_arg(ap, long long);
			} else if (size == sizeof(double)) {
				*(double *)buf = va_arg(ap, double);
			} else if (size == sizeof(long double)) {
				*(long double *)buf = va_arg(ap, long double);
			} else {
				__ASSERT(false, "unexpected size %u", size);
			}
		} else if (is_str) {
			const char *s = va_arg(ap, const char *);

			if (fsc) {
				if (s_idx >= ARRAY_SIZE(str_ptrs)) {
					return -EINVAL;
				}
				str_ptrs[s_idx++].ptr = s;
			} else if (parse_ro_str) {
				if (ptr_in_rodata(s)) {
					if (store_ro_str_idx) {
						ros_idx++;
					}
				} else {
					if (s_idx >= ARRAY_SIZE(str_ptrs)) {
						return -EINVAL;
					}
					str_ptrs[s_idx++].ptr = s;
				}
			}
		} else {
			/*
			 * We are only calculating the package size,
			 * still need to advance va_list.
			 */
			if (size == sizeof(int)) {
				(void)va_arg(ap, int);
			} else if (size == sizeof(long)) {
				(void)va_arg(ap, long);
			} else if (size == sizeof(long long)) {
				(void)va_arg(ap, long long);
			} else if (size == sizeof(double)) {
				(void)va_arg(ap, double);
			} else if (size == sizeof(long double)) {
				(void)va_arg(ap, long double);
			}
		}

		buf += size;
	}

	/*
	 * Record the size of the argument list as a multiple of
	 * sizeof(int), and store the format string pointer.
	 */
	uint8_t arg_size = (buf - buf0) / sizeof(int);

	if (buf0 != NULL) {
		union cbprintf_package_hdr *hdr = (union cbprintf_package_hdr *)buf0;
		const char **fmt_loc = (const char **)(buf0 +
			ROUND_UP(sizeof(int), VA_STACK_ALIGN(char *)));

		/* Clear header word. */
		hdr->raw = 0;
		hdr->desc.len = arg_size;

		if (fsc) {
			hdr->desc.str_cnt = 0;
			hdr->desc.ro_str_cnt = 0;
			hdr->desc.rw_str_cnt = s_idx;
		} else {
			hdr->desc.str_cnt = s_idx;
			hdr->desc.ro_str_cnt = ros_idx;
			hdr->desc.rw_str_cnt = 0;
		}

		*fmt_loc = fmt;

		/* Store indexes of read-only strings. */
		if (ros_idx) {
			if ((size_t)(buf - buf0 + ros_idx) > len) {
				return -ENOSPC;
			}

			memcpy(buf, ro_str_pos, ros_idx);
			buf += ros_idx;
		}

		/* Store strings prefixed with argument position index. */
		for (uint8_t i = 0; i < s_idx; i++) {
			size_t str_len = strlen(str_ptrs[i].ptr) + 1;

			if (fsc) {
				if ((size_t)(buf - buf0 + 1) > len) {
					return -ENOSPC;
				}
				*buf++ = str_ptrs[i].arg_idx;
				continue;
			}

			if ((size_t)(buf - buf0 + 1 + str_len) > len) {
				return -ENOSPC;
			}

			*buf++ = str_ptrs[i].arg_idx;
			memcpy(buf, str_ptrs[i].ptr, str_len);
			buf += str_len;
		}
	} else {
		buf += ros_idx;
		for (uint8_t i = 0; i < s_idx; i++) {
			size_t str_len = fsc ? 0 : (strlen(str_ptrs[i].ptr) + 1);

			buf += 1 + str_len;
		}
	}

	return (int)(buf - buf0);
}

int cbprintf_package(void *packaged, size_t len, uint32_t flags,
		     const char *format, ...)
{
	va_list ap;
	int ret;

	va_start(ap, format);
	ret = z_cbvprintf_packaged(packaged, len, flags, format, ap);
	va_end(ap);
	return ret;
}

int cbpprintf_external(cbprintf_cb out,
		       cbvprintf_external_formatter_func formatter,
		       void *ctx, void *packaged)
{
	uint8_t *buf0 = packaged;
	uint8_t *str_idx = buf0;
	unsigned int *buf = packaged;
	const char *fmt;
	union cbprintf_package_hdr *hdr = packaged;

	if (buf == NULL) {
		return -EINVAL;
	}

	/* Retrieve the size of the arg list and number of strings. */
	uint8_t arg_size = hdr->desc.len;
	uint8_t s_nbr = hdr->desc.str_cnt;
	uint8_t ros_nbr = hdr->desc.ro_str_cnt;
	uint8_t rws_nbr = hdr->desc.rw_str_cnt;

	if (rws_nbr > 0) {
		return -EINVAL;
	}

	/*
	 * Patch in the string pointers. Find the offset where strings start
	 * (past the arg list and read-only string indexes).
	 */
	str_idx += arg_size * sizeof(int) + ros_nbr;

	for (uint8_t i = 0; i < s_nbr; i++) {
		uint8_t pos = *str_idx++;
		const char **str_ptr = (const char **)&buf[pos];

		/* Point to the inlined string. */
		*str_ptr = (const char *)str_idx;
		/* Advance past the null-terminated string. */
		str_idx += strlen((const char *)str_idx) + 1;
	}

	/*
	 * Locate the format string pointer and the argument list.
	 */
	buf = (void *)ROUND_UP(buf + 1, VA_STACK_ALIGN(char *));
	fmt = *(const char **)buf;
	buf += sizeof(char *) / sizeof(int);

	/*
	 * Turn the argument list into a va_list and pass it to the
	 * formatter.
	 */
	return cbprintf_via_va_list(out, formatter, ctx, fmt, buf);
}

int cbprintf_fsc_package(void *in_packaged, size_t in_len, void *packaged,
			 size_t len)
{
	uint8_t *in_buf8 = in_packaged;
	unsigned int *in_buf = in_packaged;
	union cbprintf_package_hdr *hdr = in_packaged;
	uint8_t *out_buf8 = packaged;

	if (in_packaged == NULL) {
		return -EINVAL;
	}

	uint8_t arg_size = hdr->desc.len;
	uint8_t s_nbr = hdr->desc.str_cnt;
	uint8_t ros_nbr = hdr->desc.ro_str_cnt;
	uint8_t rws_nbr = hdr->desc.rw_str_cnt;

	/* Get pointer to the array of string indexes. */
	uint8_t *str_idx = &in_buf8[arg_size * sizeof(int)];
	/* Get length of incoming package if not specified. */
	size_t in_pkg_len = (in_len != 0) ? in_len : get_package_len(in_packaged);

	/* Calculate total size of the fsc package. */
	size_t out_len = in_pkg_len;

	for (uint8_t i = 0; i < ros_nbr; i++) {
		uint8_t idx = *str_idx++;
		const char *str = *(const char **)&in_buf[idx];

		out_len += strlen(str) + 1;
	}

	/* Skip past appended strings. */
	for (uint8_t i = 0; i < s_nbr; i++) {
		str_idx++;
		str_idx += strlen((const char *)str_idx) + 1;
	}

	for (uint8_t i = 0; i < rws_nbr; i++) {
		uint8_t idx = *str_idx++;
		const char *str = *(const char **)&in_buf[idx];

		out_len += strlen(str) + 1;
	}

	/* If output buffer is specified, check size and copy data. */
	if (packaged != NULL) {
		if (out_len > len) {
			return -ENOSPC;
		}

		/* Copy header and arguments. */
		size_t hdr_args_len = arg_size * sizeof(int);

		if (in_packaged != packaged) {
			memcpy(out_buf8, in_buf8, hdr_args_len);
		}
		out_buf8 += hdr_args_len;

		/* Update header in the output package. */
		union cbprintf_package_hdr *out_hdr = packaged;

		out_hdr->desc.str_cnt = s_nbr + ros_nbr + rws_nbr;
		out_hdr->desc.ro_str_cnt = 0;
		out_hdr->desc.rw_str_cnt = 0;

		/* Append formerly read-only strings. */
		str_idx = &in_buf8[hdr_args_len];
		for (uint8_t i = 0; i < ros_nbr; i++) {
			uint8_t idx = *str_idx++;
			const char *str = *(const char **)&in_buf[idx];
			size_t slen = strlen(str) + 1;

			*out_buf8++ = idx;
			memcpy(out_buf8, str, slen);
			out_buf8 += slen;
		}

		/* Copy already appended strings. */
		for (uint8_t i = 0; i < s_nbr; i++) {
			uint8_t idx = *str_idx++;
			size_t slen = strlen((const char *)str_idx) + 1;

			*out_buf8++ = idx;
			memcpy(out_buf8, str_idx, slen);
			out_buf8 += slen;
			str_idx += slen;
		}

		/* Append RW strings which were only indexed. */
		for (uint8_t i = 0; i < rws_nbr; i++) {
			uint8_t idx = *str_idx++;
			const char *str = *(const char **)&in_buf[idx];
			size_t slen = strlen(str) + 1;

			*out_buf8++ = idx;
			memcpy(out_buf8, str, slen);
			out_buf8 += slen;
		}
	}

	return out_len;
}

int cbprintf_package_copy(void *in_packaged, size_t in_len, void *packaged,
			  size_t len, uint32_t flags, ...)
{
	if ((flags & CBPRINTF_PACKAGE_CONVERT_RO_STR) &&
	    !(flags & CBPRINTF_PACKAGE_CONVERT_RW_STR)) {
		/* Supported only when RW strings are also converted or kept. */
	}

	return cbprintf_fsc_package(in_packaged, in_len, packaged, len);
}
